// Create utility for session storage: lib/session-storage.ts
const SESSION_KEY_PREFIX = 'wrext-topic-session-';
const SESSION_EXPIRY = 24 * 60 * 60 * 1000; // 24 hours

export interface SessionData {
  id: string;
  topics: GeneratedTopic[];
  formData: TopicBuilderFormData;
  createdAt: number;
  expiresAt: number;
}

export const saveSession = (data: Omit<SessionData, 'createdAt' | 'expiresAt'>) => {
  const now = Date.now();
  const sessionData: SessionData = {
    ...data,
    createdAt: now,
    expiresAt: now + SESSION_EXPIRY
  };

  localStorage.setItem(
    `${SESSION_KEY_PREFIX}${data.id}`,
    JSON.stringify(sessionData)
  );
};

export const getSession = (id: string): SessionData | null => {
  const data = localStorage.getItem(`${SESSION_KEY_PREFIX}${id}`);
  if (!data) return null;

  const session = JSON.parse(data) as SessionData;

  // Check if session has expired
  if (Date.now() > session.expiresAt) {
    localStorage.removeItem(`${SESSION_KEY_PREFIX}${id}`);
    return null;
  }

  return session;
};

// Create results page: app/ideas/create/results/[temporaryId]/page.tsx
'use client';

import { useEffect, useState } from 'react';
import { useParams } from 'next/navigation';
import { getSession } from '@/lib/session-storage';
import { Breadcrumb } from '@/components/ui/breadcrumb';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { TopicCard } from '@/components/topic-builder/results/TopicCard';
import { BulkActions } from '@/components/topic-builder/results/BulkActions';

export default function ResultsPage() {
  const { temporaryId } = useParams();
  const [session, setSession] = useState<SessionData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (temporaryId) {
      const sessionData = getSession(temporaryId as string);
      if (sessionData) {
        setSession(sessionData);
      } else {
        setError('Session not found or expired');
      }
    }
    setLoading(false);
  }, [temporaryId]);

  if (loading) {
    return <div>Loading...</div>;
  }

  if (error || !session) {
    return (
      <Alert variant="destructive">
        <AlertTitle>Session Error</AlertTitle>
        <AlertDescription>
          {error || 'Unable to load session data. The session may have expired.'}
        </AlertDescription>
      </Alert>
    );
  }

  return (
    <div className="space-y-6">
      <Breadcrumb items={[
        { label: 'Dashboard', href: '/' },
        { label: 'Ideas', href: '/ideas' },
