// Create BulkActions component: components/topic-builder/results/BulkActions.tsx
import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dropdown, DropdownTrigger, DropdownContent, DropdownItem } from '@/components/ui/dropdown';
import { toast } from '@/components/ui/toast';
import { GeneratedTopic } from '@/types/topic-builder';

interface BulkActionsProps {
  topics: GeneratedTopic[];
  selectedIds?: string[];
  onSelectAll?: (selected: boolean) => void;
  onClearSelection?: () => void;
}

export const BulkActions = ({ 
  topics, 
  selectedIds = [], 
  onSelectAll, 
  onClearSelection 
}: BulkActionsProps) => {
  const hasSelection = selectedIds.length > 0;

  const handleSaveAll = async () => {
    try {
      // Filter topics by selected IDs
      const topicsToSave = topics.filter(topic => selectedIds.includes(topic.id));

      // Call API to save topics
      const response = await fetch('/api/topics/bulk-save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ topics: topicsToSave })
      });

      if (!response.ok) throw new Error('Failed to save topics');

      toast({
        title: 'Topics Saved',
        description: `Successfully saved ${selectedIds.length} topics.`
      });

      // Clear selection after save
      if (onClearSelection) onClearSelection();
    } catch (error) {
      toast({
        title: 'Error',
        description: error.message,
        variant: 'destructive'
      });
    }
  };

  const handleExport = async (format: 'json' | 'csv') => {
    try {
      // Filter topics by selected IDs
      const topicsToExport = topics.filter(topic => 
        selectedIds.length ? selectedIds.includes(topic.id) : true
      );

      let content: string;
      let filename: string;
      let type: string;

      if (format === 'json') {
        content = JSON.stringify(topicsToExport, null, 2);
        filename = 'topics-export.json';
        type = 'application/json';
      } else {
        // Convert to CSV
        const headers = 'Title,Description,Keywords,Relevance Score,Audience Fit\n';
        const rows = topicsToExport.map(topic => {
          return `"${topic.title.replace(/"/g, '""')}","${topic.description.replace(/"/g, '""')}","${topic.keywords.join(', ')}",${topic.relevance_score},${topic.audience_fit}`;
        }).join('\n');

        content = headers + rows;
        filename = 'topics-export.csv';
        type = 'text/csv';
      }

      // Create download link
      const blob = new Blob([content], { type });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast({
        title: 'Export Complete',
        description: `Successfully exported ${topicsToExport.length} topics as ${format.toUpperCase()}.`
      });
    } catch (error) {
      toast({
        title: 'Export Error',
        description: error.message,
        variant: 'destructive'
      });
    }
  };

  return (
    <div className="flex items-center gap-2">
      {onSelectAll && (
        <Button 
          variant="outline" 
          size="sm"
          onClick={() => onSelectAll(true)}
        >
          Select All
        </Button>
      )}

      {hasSelection && onClearSelection && (
        <Button 
          variant="ghost" 
          size="sm"
          onClick={onClearSelection}
        >
          Clear Selection ({selectedIds.length})
        </Button>
      )}

      <Dropdown>
        <DropdownTrigger asChild>
          <Button variant="outline" size="sm">
            Export
          </Button>
        </DropdownTrigger>
        <DropdownContent>
          <DropdownItem onClick={() => handleExport('json')}>Export as JSON</DropdownItem>
          <DropdownItem onClick={() => handleExport('csv')}>Export as CSV</DropdownItem>
        </DropdownContent>
      </Dropdown>

      {hasSelection && (
        <Button 
          variant="default" 
          size="sm"
          onClick={handleSaveAll}
        >
          Save Selected ({selectedIds.length})
        </Button>
      )}
    </div>
  );
};
```

